    let geoBlazorId = lookupGeoBlazorId(jsObject);
    if (hasValue(geoBlazorId)) {
        dotNetFeatureTableViewModel.id = geoBlazorId;
    } else if (hasValue(viewId)) {
        let dotNetRef = dotNetRefs[viewId!];
        if (hasValue(dotNetRef)) {
            try {
                dotNetFeatureTableViewModel.id = await dotNetRef.invokeMethodAsync('GetId');
            } catch (e) {
                console.error('Error invoking GetId for FeatureTableViewModel', e);
            }
        }
    }

    if (hasValue(dotNetFeatureTableViewModel.id)) {
        if (!jsObjectRefs.hasOwnProperty(dotNetFeatureTableViewModel.id)) {
            let { default: FeatureTableViewModelWrapper } = await import('./featureTableViewModel');
            let featureTableViewModelWrapper = new FeatureTableViewModelWrapper(jsObject);
            featureTableViewModelWrapper.geoBlazorId = dotNetFeatureTableViewModel.id;
            featureTableViewModelWrapper.viewId = viewId;
            featureTableViewModelWrapper.layerId = layerId;
            jsObjectRefs[dotNetFeatureTableViewModel.id] = featureTableViewModelWrapper;
        }
        arcGisObjectRefs[dotNetFeatureTableViewModel.id] ??= jsObject;
    }
